<?php defined('BASEPATH') or exit('No direct script access allowed');$team=[];foreach($salespersons as $r){$policy=scaf_rep_policy($r['id']);if(!$policy)continue;$c=$policy['currency'];if(!isset($team[$c]))$team[$c]=['target'=>'0','closed'=>'0'];$team[$c]['target']=scaf_decimal_add($team[$c]['target'],$policy['monthly_target']);$team[$c]['closed']=scaf_decimal_add($team[$c]['closed'],$rep_metrics['reps'][(int)$r['id']]['closed'][$c]??'0');} ?>
<section class="scaf-rep-kpis"><div><span><?= e(scaf_rep_label('Active closers','Representantes activos')); ?></span><strong><?= (int)$rep_metrics['active']; ?></strong></div><div><span><?= e(scaf_rep_label('Closed invoice volume · MTD','Volumen de facturas cerradas · mes')); ?></span><strong><?= scaf_rep_money($rep_metrics['groups']); ?></strong></div><div><span><?= e(scaf_rep_label('Monthly team quota attainment','Cumplimiento de cuota mensual')); ?></span><?php if(!$team){ ?><strong><?= e(scaf_rep_label('Unconfigured','Sin configurar')); ?></strong><?php }foreach($team as $c=>$g){ ?><strong><?= e($c.' '.number_format((float)$g['closed']/(float)$g['target']*100,1).'%'); ?></strong><?php } ?></div><div><span><?= e(scaf_rep_label('Average configured commission rate','Promedio de comisión configurada')); ?></span><strong><?= e($rep_metrics['rate_count']?number_format((float)$rep_metrics['rate_sum']/$rep_metrics['rate_count'],2):'0.00'); ?>%</strong></div></section>
<p class="text-muted"><?= e(scaf_rep_label('Closed volume: linked paid invoices whose latest cash payment is this month. Shared invoices count once for the team. Legacy sales goals have no monthly period or currency and are not treated as monthly quotas.','Volumen cerrado: facturas pagadas vinculadas cuyo último pago es de este mes. Las facturas compartidas se cuentan una vez para el equipo. Las metas antiguas no tienen período mensual ni moneda.')); ?></p>
